INSERT INTO `guide_article` VALUES (1, '升学规划', '升学路径', '国际教育常见问题-小学阶段', '\r\n1. 小学阶段转轨常见问题：\r\n   - 何时转轨最合适？幼升小、小升初均为黄金窗口期。\r\n   - 幼升小/低年级入读：孩子能更早融入国际教育氛围，对新语言接受能力更强；但可能面临理科学习不够深入、中文读写能力受影响等问题。\r\n   - 小升初入读：可在公办学校培养良好学习习惯后再转学；挑战是需要适应全新的学习方式和课程评估体系。\r\n   - 最晚不应超过五年级转轨，以顺利衔接国际初中课程。\r\n2. 家长需关注的三大核心：\r\n   - 学籍管理：非纯外籍国际学校通常保留国内学籍，需通过官方渠道核查学校资质。\r\n   - 入学准备：除英语标化成绩外，面试更注重批判性思维展示。\r\n   - 课程适应：全英文授课环境需提前积累学科词汇，家长需接纳\"试错教育\"理念。\r\n3. 转轨本质是教育生态的切换，建议家长建立\"三年观察期\"，通过参加开放日、与在读家庭交流等方式构建立体化认知。\r\n', NULL, NULL, 1, '2026-07-21 10:27:15');
INSERT INTO `guide_article` VALUES (2, '升学规划', '升学路径', '国际教育是什么？一图看懂国际教育', NULL, NULL, NULL, 2, '2026-07-21 10:27:15');
INSERT INTO `guide_article` VALUES (3, '升学规划', '升学路径', '从小学到大学，这几条升学路径你知道吗？', '\r\n国内升学与国际升学主要路径概览：\r\n\r\n1. 国内高考路线：\r\n   - 小学→初中→高中→国内大学（或中外合作办学、出国留学）。\r\n   - 优势：费用低，基础教育扎实，适合学术型学生。\r\n\r\n2. 国际教育路线：\r\n   - 国际小学→国际初中→国际高中→海外大学。\r\n   - 优势：全人教育，培养批判性思维和语言能力，申请海外名校更具竞争力。\r\n\r\n3. 混合路线（中途转轨）：\r\n   - 可小学、初中或高中阶段转入国际学校，需提前规划英语和学科衔接。\r\n\r\n4. 升学关键节点：\r\n   - 幼升小、小升初、初升高为重要转轨期，建议提前1-2年准备。\r\n   - 三类孩子适配国际赛道：一是学有余力、目标世界名校的学霸；二是不适应应试体系的学生；三是明确出国意向的学生。[reference:0]\r\n', NULL, NULL, 3, '2026-07-21 10:27:15');
INSERT INTO `guide_article` VALUES (4, '升学规划', '升学路径', '国内高考路线和国际教育路线如何升读大学？有什么差异点', '国内高考路线和国际教育路线是两种不同的教育路径，它们各自有不同的特点和优势。以下是对这两种路线的概述：\r\n\r\n1、 国内高考路线有以下几种方式可以就读大学\r\n\r\n方式一：直接报考国内大学\r\n\r\n大学学生通过中考升入普通高中，最终参加全国统一高考，以获取进入国内大学的资格。\r\n\r\n方式二：特殊招生\r\n\r\n包括自主招生、专项计划、艺术类高考等，为特定条件的学生提供额外的升学机会。\r\n\r\n方式三： 中外合作办学\r\n\r\n如\"4+0、2+2、3+1\"模式的中外合作大学项目，学生在国内完成学业后，可以获得国外大学的学位证书。\r\n\r\n方式四：海外留学\r\n\r\n学生可以凭借高考成绩、高中平时成绩或者AST遴选，直接申请海外大学，出国就读大学。\r\n\r\n\r\n\r\n2、国际教育路线如何就读大学？\r\n\r\n方式一：出国留学\r\n\r\n国际高中生的第一选择还是出国留学。学生按照课程要求参加A-Llevel/AP/IB等全球大考，拿到课程证书或者成绩单，在高三上学期，凭平时成绩、统考成绩、语言成绩、竞赛证书等一系列材料，向国外大学提出入学申请。\r\n\r\n方式二：读中国香港、中国澳门的大学\r\n\r\n不想离家太远，或者学习的是DSE课程的国际高中生，会报考中国香港、中国澳门的大学。这些学校也是要求学生提供平时表现+统考成绩+竞赛证书等材料，学校综合这些材料择优录取。\r\n\r\n方式三：读国内大学的国际本科项目\r\n\r\n不想高中毕业直接出国，可以报考国内大学的国际本科项目。是指开设2+2、3+1、4+0等本科留学项目的高校，可以让国际高中学生延缓2-3年出国留学，节省留学费用，同时还可以提升雅思或托福成绩，申请国外更好的大学。\r\n\r\n例如，伯明翰“1+3”本科直升计划，国内学一年的伯明翰大学先修学术课程，次年直录伯明翰大学本科，实现自己的英国名校梦想。\r\n\r\n\r\n\r\n总之，选择国内高考还是选择国际学校，都是有很多升学路线可以选择的，无论是选择国内高校还是出国深造，都需要学生有足够的准备和竞争力。家长和学生应该根据自己的需求和兴趣，选择最适合自己的升学路线，并在学习过程中付出足够的努力和汗水，为自己的未来打下坚实的基础。\r\n\r\n\r\n\r\n如果对于孩子升学路线不明确，不知道孩子适合国内高考还是走国际路线，可以点击下方在线咨询，一对一制定适合孩子的升学路线！', NULL, NULL, 4, '2026-07-21 10:27:15');
INSERT INTO `guide_article` VALUES (5, '升学规划', '升学路径', '纯国际教育路线（小初高都在国际学校就读）的优势及规划建议', '\r\n**核心优势：**\r\n1. 语言与文化浸润：长期英文环境，培养母语级英语能力。\r\n2. 全人教育：注重个性发展、批判性思维和综合素养。\r\n3. 升学连贯性：避开中考、高考压力，直升国际高中，衔接海外大学。\r\n\r\n**规划建议：**\r\n1. 小学阶段：重点培养英语兴趣和阅读习惯，参加趣味性活动。\r\n2. 初中阶段：强化学术英语，探索学科兴趣，参加学科竞赛。\r\n3. 高中阶段：明确升学方向（英/美/加等），准备标化考试和背景提升。\r\n\r\n**注意事项：**\r\n- 需具备较强的家庭经济实力，需提前规划语言学习[reference:1]。\r\n- 孩子需适应双语环境，家长要关注心理健康。\r\n- 培养孩子的批判性思维及语言能力是核心思路。\r\n', NULL, NULL, 5, '2026-07-21 10:27:15');
INSERT INTO `guide_article` VALUES (6, '升学规划', '升学路径', '初中转轨国际学校优势及规划建议', '\r\n**核心优势：**\r\n1. 小学阶段体制内教育夯实了学科基础和学习习惯。\r\n2. 初中转轨可跨过中考这道坎，提前适应国际教育体系[reference:2]。\r\n3. 提前融入英文授课环境，有更多时间拓展兴趣爱好、探索职业方向。\r\n\r\n**注意事项：**\r\n1. 英语能力不足会导致适应困难，需提前培养英语能力和独立自主、开放性思维。\r\n2. 青春期孩子对环境变化敏感，家长需多关注孩子情绪是否适应。\r\n\r\n**规划建议：**\r\n1. 提前规划雅思/托福等语言学习、双语数学、竞赛等[reference:3]。\r\n2. 参加国际学校入学笔面试培训。\r\n\r\n**核心思路：** 抓好英语+双语数学。\r\n', NULL, NULL, 6, '2026-07-21 10:27:15');
INSERT INTO `guide_article` VALUES (7, '升学规划', '规划须知', '选择给孩子规划国际教育路线，家长需要考虑哪几个方面？', '\r\n选择国际教育路线，家长需从以下四个方面综合考量：\r\n\r\n1. **经济条件**：\r\n   - 国内国际学校年费用约20-40万；留学年费用约30-60万（视地区而定）。\r\n   - 需长远规划，确保能覆盖孩子从小学到大学的全部费用。\r\n\r\n2. **家庭背景**：\r\n   - 父母教育观念是否开放国际化，能否接受孩子在留学过程中的转变。\r\n\r\n3. **孩子性格特点**：\r\n   - 适应能力强、能独立生活并应对文化冲突的孩子更适合。\r\n   - 适应能力较弱的孩子需慎重考虑。\r\n\r\n4. **社会资源**：\r\n   - 国内教育相对公平，不依赖社会资源。\r\n   - 出国留学时，社会资源（实习机会、职业网络等）显得更为重要。\r\n\r\n**核心原则**：没有一种路径是绝对最好的，只有最适合孩子的才是最佳选择[reference:5]。\r\n', NULL, NULL, 1, '2026-07-21 10:27:15');
INSERT INTO `guide_article` VALUES (8, '升学规划', '规划须知', '哪些孩子适合就读国际教育路线？', '\r\n原则上，没有绝对的\"适合\"或\"不适合\"，需综合以下因素判断：\r\n\r\n1. **经济基础是前提**：家庭经济条件充足，选择国际学校或出国留学才成为可行选项。\r\n\r\n2. **家长需明确几个核心问题**：\r\n   - 为什么要选择国际教育？\r\n   - 孩子的性格特征是否适合这条路线？\r\n   - 选择国际路线可能带来什么副作用，这些是否是你所希望的？\r\n\r\n3. **三类孩子适配国际赛道**[reference:6]：\r\n   - 学有余力、目标世界名校的学霸，可双线准备。\r\n   - 不适应应试体系的学生。\r\n   - 明确出国意向、心仪海外专业的孩子。\r\n\r\n**核心原则**：没有一种路径是绝对最好的，只有最适合孩子的才是最佳选择[reference:7]。\r\n', NULL, NULL, 2, '2026-07-21 10:27:15');
INSERT INTO `guide_article` VALUES (9, '升学规划', '升学路径', '高中转轨国际学校，初中三年该如何规划？', '\r\n**核心优势：**\r\n1. 小学和初中在公立学校打下良好的理科学习基础。\r\n2. 长线养成中式学习习惯，学会自我管理，与国际高中衔接顺畅。\r\n3. 性价比高，省下小学和初中阶段的国际学校费用。\r\n\r\n**注意事项：**\r\n相比小学和初中在国际学校的学生，英语基础和批判性思维可能相对薄弱。\r\n\r\n**初中三年规划建议：**\r\n1. 初一初二：保持校内成绩，寒暑假提前学习英语，积累学术词汇。\r\n2. 初三：提前规划雅思/托福学习，保持校内成绩，学习双语数学[reference:4]。\r\n3. 参加背景提升活动，如学科竞赛、科研项目、研学等。\r\n4. 早点进行国际学校择校，准备入学笔面试。\r\n\r\n**核心思路：** 抓好英语+双语数学。\r\n', NULL, NULL, 3, '2026-07-21 10:27:15');
INSERT INTO `guide_article` VALUES (10, '升学规划', '规划须知', '一次性说清楚国际学校规划时间安排，怎样安排时间更合理', '\r\n国际学校申请至少需提前1-2年规划，全年关键时间线如下：\r\n\r\n**1月-2月**：\r\n- 了解国际课程体系（A-Level/AP/IB/OSSD/DSE等）及其升学方向。\r\n- 了解各国际学校的口碑、资质、升学成绩、入学考试要求。\r\n- 幼升小/小升初：准备入学资料，提高孩子英语听说能力。\r\n- 初升高：收集开放日信息，注意报考截止时间。\r\n\r\n**3月-4月**：\r\n- 国际学校招生季，学校举办开放日、宣讲会等活动。\r\n- 参加入学考试。初升高学生需权衡中考与入学考试备考。\r\n\r\n**5月-6月**：\r\n- 中考后迎来\"补录\"小高峰，招生比例约10%。\r\n- 补录名额有限，竞争激烈，需关注学校官网信息[reference:8]。\r\n\r\n**7月-8月**：\r\n- 入学前语言学习黄金期。国际学校全英文授课，雅思/托福需提前准备[reference:9]。\r\n- 按照雅思6-7分为目标做语言准备。\r\n\r\n**9月-12月**：\r\n- 国际学校春招及开放日高峰，可考虑插班生考试。\r\n- 参加开放日、课堂体验等活动，确定\"意向学校\"。\r\n', NULL, NULL, 4, '2026-07-21 10:27:15');
