INSERT INTO `guide_article` VALUES (12, '升学规划', '学校介绍', '2025年上海公立国际部招生分数线及区排名', NULL, NULL, NULL, 2, '2026-07-21 10:27:15');
INSERT INTO `guide_article` VALUES (13, '升学规划', '学校介绍', '国际学校三大类型全解析', '\r\n国际学校主要分为三大类型：\r\n\r\n1. **外籍人员子女学校**：\r\n   - 招生对象：仅招收持有外国护照或港澳台身份的学生。\r\n   - 课程体系：通常采用本国课程或国际课程（IB/AP/A-Level）。\r\n   - 代表学校：上海美国学校、上海英国学校等。\r\n\r\n2. **公立学校国际部/国际班**：\r\n   - 招生对象：通常招收本地户籍学生，需通过中考或校内选拔。\r\n   - 课程体系：国家课程+国际课程融合，如IBDP、AP等。\r\n   - 代表学校：上海中学国际部、华师大二附中国际部等。\r\n   - 优势：学费相对较低，生源质量高。\r\n\r\n3. **民办国际学校**：\r\n   - 招生对象：不限户籍，面向全国招生。\r\n   - 课程体系：多元化，涵盖IB、AP、A-Level等主流课程。\r\n   - 代表学校：包玉刚实验学校、平和双语学校、世外中学等。\r\n   - 优势：课程选择灵活，硬件设施好。\r\n\r\n**择校建议**：根据家庭情况、孩子特点和升学目标综合选择。\r\n', NULL, NULL, 3, '2026-07-21 10:27:15');
INSERT INTO `guide_article` VALUES (14, '升学规划', '学校介绍', '上海| 上海外籍人员子女学校分布', NULL, NULL, NULL, 4, '2026-07-21 10:27:15');
INSERT INTO `guide_article` VALUES (15, '升学规划', '学校介绍', '上海 | 上海国际学校各区分布', NULL, NULL, NULL, 5, '2026-07-21 10:27:15');
INSERT INTO `guide_article` VALUES (16, '升学规划', '课程体系', 'A-Level课程 | 三大考试局科目A*率对比', NULL, NULL, NULL, 1, '2026-07-21 10:27:15');
INSERT INTO `guide_article` VALUES (17, '升学规划', '课程体系', 'A-Level课程 | 不同专业方向选科指南', '\r\nA-Level选科应结合目标专业方向，以下为常见专业方向的选科建议：\r\n\r\n**1. 医学/兽医/牙科**：\r\n- 必修：生物、化学\r\n- 推荐：数学、物理\r\n\r\n**2. 工程/计算机科学**：\r\n- 必修：数学\r\n- 推荐：物理、进阶数学、计算机科学\r\n\r\n**3. 自然科学（物理/化学/生物）**：\r\n- 必修：数学、目标学科\r\n- 推荐：进阶数学、另一门科学\r\n\r\n**4. 经济/金融/商科**：\r\n- 推荐：数学、经济、进阶数学、商务\r\n\r\n**5. 法律**：\r\n- 推荐：数学、历史、英语文学、法律（如开设）\r\n\r\n**6. 艺术与设计**：\r\n- 推荐：艺术、数学、设计技术\r\n\r\n**通用原则**：\r\n- 目标英国G5/香港大学：建议至少选择2门硬学科（数学、科学类）。\r\n- 部分大学专业有明确科目要求，建议提前查阅目标院校官网。\r\n', NULL, NULL, 2, '2026-07-21 10:27:15');
INSERT INTO `guide_article` VALUES (18, '升学规划', '课程体系', 'A-Level课程三大考试局对比', '\r\nA-Level课程由三大考试局提供，核心区别如下：\r\n\r\n1. **剑桥大学国际考试委员会（CAIE）**：\r\n   - 特点：全球统一命题，每年5-6月和10-11月两次考试。\r\n   - 适用地区：全球160多个国家，适合申请英联邦国家。\r\n   - 难度：理科难度相对较高。\r\n\r\n2. **爱德思（Edexcel）**：\r\n   - 特点：英国本土及国际版并行，每年1-2月、5-6月、10-11月三次考试。\r\n   - 适用地区：英国、全球国际学校。\r\n   - 难度：考试内容较为灵活。\r\n\r\n3. **牛津AQA**：\r\n   - 特点：2017年进入中国市场，命题更注重逻辑思维。\r\n   - 适用地区：全球国际学校。\r\n   - 难度：文科内容相对更深入。\r\n\r\n**选择建议**：\r\n- 三大考试局成绩效力等同，均受全球大学认可。\r\n- 学生可自由选择不同考试局科目组合。\r\n- 各校合作考试局不同，择校时可重点关注。\r\n', NULL, NULL, 3, '2026-07-21 10:27:15');
INSERT INTO `guide_article` VALUES (19, '升学规划', '课程体系', '一张图介绍清楚【IGCSE课程】', NULL, NULL, NULL, 4, '2026-07-21 10:27:15');
