INSERT INTO `guide_article` VALUES (24, '升学规划', '课程体系', '一文了解国际学校课程体系（A-Level、AP、IB）', '\r\n三大主流国际课程体系核心对比：\r\n\r\n**1. IB课程（国际文凭课程）**：\r\n- 特点：全面发展，需修读6大学科组+3大核心课程（TOK、EE、CAS）。\r\n- 适合学生：文理均衡、时间管理能力强的学生。\r\n- 评估方式：校内评估+全球统考。\r\n\r\n**2. AP课程（美国大学先修课程）**：\r\n- 特点：单科进阶，可自由选择科目数量。\r\n- 适合学生：有明确学科兴趣、目标美国大学的学生。\r\n- 评估方式：全球统一考试。\r\n\r\n**3. A-Level课程（英国高中课程）**：\r\n- 特点：深度专精，选择3-4门科目深入学习。\r\n- 适合学生：有明确专业方向、擅长深度学习的学生。\r\n- 评估方式：全球统一考试。\r\n\r\n**选择建议**：\r\n- IB：追求全人教育、目标全球顶尖大学。\r\n- AP：目标美国大学、希望展示学术竞争力。\r\n- A-Level：目标英联邦国家、有明确专业方向。\r\n\r\n**核心差异**：IB强调广度，AP/A-Level强调深度。\r\n', NULL, NULL, 9, '2026-07-21 10:27:15');
INSERT INTO `guide_article` VALUES (25, '择校探校', '择校须知', '国际学校择校6步骤，帮孩子选择更适合的学校！', '\r\n国际学校择校可遵循以下6个步骤：\r\n\r\n**第一步：明确需求**\r\n- 确定升学目标（国家/方向）、课程体系偏好、预算范围。\r\n\r\n**第二步：收集信息**\r\n- 通过学校官网、教育展会、择校平台等渠道收集学校信息。\r\n\r\n**第三步：筛选初选**\r\n- 根据学校资质、师资力量、升学成果等维度初步筛选3-5所目标校。\r\n\r\n**第四步：实地探校**\r\n- 参加学校开放日，考察校园环境，与招生官和在校学生交流。\r\n\r\n**第五步：对比评估**\r\n- 从课程设置、师资稳定性、课外活动、家校沟通等维度综合对比。\r\n\r\n**第六步：参加考试**\r\n- 准备入学笔面试，部分学校需提交标化成绩。\r\n\r\n**择校维度参考**：办学理念→课程体系→校长团队→师资力量→升学成果→社会资源，六大维度缺一不可。\r\n', NULL, NULL, 1, '2026-07-21 10:44:31');
INSERT INTO `guide_article` VALUES (26, '择校探校', '择校须知', '选公立学校国际部还是国际学校？', '\r\n公立学校国际部与民办国际学校的主要区别：\r\n\r\n**公立学校国际部**：\r\n- **招生**：通常限本地户籍，需通过中考或校内选拔。\r\n- **学费**：相对较低，性价比高。\r\n- **生源**：学生经过筛选，学习氛围较好。\r\n- **课程**：以国家课程为基础，融合国际课程。\r\n- **适合学生**：学术能力强、目标明确、适应中式管理的学生。\r\n\r\n**民办国际学校**：\r\n- **招生**：不限户籍，全国招生。\r\n- **学费**：较高，年费用约20-40万。\r\n- **生源**：多元化，注重综合素养。\r\n- **课程**：体系灵活，可自主选择IB/AP/A-Level等。\r\n- **适合学生**：追求全人教育、需要个性化发展的学生。\r\n\r\n**选择建议**：评估孩子性格（自律/需要引导）、家庭经济状况及目标留学国家后综合决定。\r\n', NULL, NULL, 2, '2026-07-21 10:44:31');
INSERT INTO `guide_article` VALUES (27, '择校探校', '择校须知', '不想卷的孩子适合上公立国际部还是国际学校？', '\r\n\"不想卷\"需区分两种情况，选择建议如下：\r\n\r\n**情况一：孩子不适应应试高压，但愿意学习**：\r\n- 推荐民办国际学校：注重全人教育和个性化发展，评价体系多元化。\r\n- 可通过丰富的课外活动和项目式学习激发学习兴趣。\r\n- 适合有明确出国意向、追求综合发展的学生。\r\n\r\n**情况二：孩子缺乏学习动力，家长希望\"躺平\"升学**：\r\n- 需慎重考虑：两条路线最终都要面临升学竞争。\r\n- 国际路线虽然不以\"分数\"为唯一标准，但同样需要持续的努力和投入。\r\n- 建议与孩子充分沟通，明确升学目标后再做决定。\r\n\r\n**核心观点**：\r\n- \"不卷\"不等于\"不努力\"，国际路线对学生的自律性和时间管理能力要求更高。\r\n- 适合度比\"轻松度\"更重要，建议根据孩子性格特点和发展潜力来选择。\r\n', NULL, NULL, 3, '2026-07-21 10:44:31');
INSERT INTO `guide_article` VALUES (28, '择校探校', '实地探校', '国际学校探校怎么探，探校时家长一定要问清楚的那些问题！', '\r\n探校是择校的关键环节，建议家长提问以下核心问题：\r\n\r\n**1. 关于课程与教学**：\r\n- 学校的课程体系是什么？是否获得官方授权？\r\n- 中外教比例是多少？外教稳定性如何？\r\n- 每天的课时安排和作业量如何？\r\n\r\n**2. 关于升学成果**：\r\n- 近三年毕业生主要去向哪些国家和大学？\r\n- 学校如何支持学生进行升学规划？\r\n\r\n**3. 关于学生管理**：\r\n- 学校如何处理学生之间的矛盾和冲突？\r\n- 是否有心理健康支持体系？如何运作？\r\n\r\n**4. 关于家校沟通**：\r\n- 家长与学校的沟通渠道有哪些？频率如何？\r\n- 学校是否定期组织家长会或家长课堂？\r\n\r\n**5. 关于费用**：\r\n- 除学费外，还有哪些额外费用（校服、餐费、校车、研学等）？\r\n\r\n探校时应多观察校园细节，与在校学生和老师深入交流。\r\n', NULL, NULL, 1, '2026-07-21 10:44:31');
INSERT INTO `guide_article` VALUES (29, '择校探校', '实地探校', '如何考察一所国际学校？10个维度教你对话校长、老师和家长', '\r\n考察国际学校可从以下10个维度进行：\r\n\r\n**与校长对话**：\r\n1. 学校的办学理念和使命是什么？\r\n2. 学校未来的发展规划和目标是什么？\r\n3. 校长如何看待当前教育趋势和学校定位？\r\n\r\n**与老师对话**：\r\n4. 课堂教学采用什么方式？如何评估学生的学习效果？\r\n5. 老师如何关注和帮助学生个体差异？\r\n6. 老师对学生的期望值是什么？如何激发学生潜力？\r\n\r\n**与在校家长对话**：\r\n7. 您当初为什么选择这所学校？入读后是否符合预期？\r\n8. 学校在哪些方面做得特别好？哪些方面有待改进？\r\n9. 家校沟通是否顺畅？学校对家长意见的反馈如何？\r\n10. 孩子的综合成长（学术、社交、心理）是否满意？\r\n\r\n**总结**：通过与多方深入交流，构建立体化的学校认知，避免片面判断。\r\n', NULL, NULL, 2, '2026-07-21 10:44:31');
INSERT INTO `guide_article` VALUES (30, '择校探校', '实地探校', '国际学校探校的时候最容易忽视的几个问题！？', '\r\n探校时以下问题容易被家长忽视，但至关重要：\r\n\r\n**1. 学生的真实状态**：\r\n- 观察课间学生的行为举止、精神面貌。\r\n- 观察学生之间的互动，是否友善、尊重。\r\n\r\n**2. 校园的细节管理**：\r\n- 教室、图书馆、餐厅、卫生间的整洁程度。\r\n- 公告栏的内容和更新频率。\r\n- 校园安全设施（门禁、监控、消防等）。\r\n\r\n**3. 非核心课程的支持**：\r\n- 学校的心理咨询室是否配备专业心理老师？\r\n- 大学升学指导服务如何运作？\r\n- ESL/EAL支持体系是否完善？\r\n\r\n**4. 家校沟通的实际体验**：\r\n- 与在校家长交流，了解真实的家校沟通体验。\r\n- 学校对家长意见的响应速度和处理方式。\r\n\r\n**5. 课程安排的合理性**：\r\n- 体育课、艺术课、课外活动的实际课时占比。\r\n- 作业量的合理性，学生是否有充足的睡眠时间。\r\n', NULL, NULL, 3, '2026-07-21 10:44:31');
INSERT INTO `guide_article` VALUES (31, '择校探校', '学校开放日', '国际学校为什么要做开放日？', '\r\n国际学校举办开放日的核心目的包括：\r\n\r\n**对学校而言**：\r\n1. **展示办学实力**：通过开放日向家长展示学校的教育理念、师资力量和硬件设施。\r\n2. **吸引优质生源**：开放日是学校最主要的招生宣传渠道。\r\n3. **建立品牌形象**：通过开放日活动提升学校的社会认知度和美誉度。\r\n4. **促进家校信任**：与家长面对面沟通，建立信任基础。\r\n\r\n**对家长而言**：\r\n1. **了解真实情况**：进入校园亲身感受学校的氛围和环境。\r\n2. **与关键人员交流**：有机会与校长、老师、招生官直接对话。\r\n3. **比较选择**：通过参加多所学校的开放日进行横向对比。\r\n4. **获取申请信息**：了解招生政策、申请流程和入学要求。\r\n\r\n**核心价值**：开放日是家长了解学校最直接、最全面的窗口，建议家长积极预约参加。\r\n', NULL, NULL, 1, '2026-07-21 10:44:31');
INSERT INTO `guide_article` VALUES (32, '择校探校', '学校开放日', '国际学校开放日流程有哪些？', '\r\n国际学校开放日通常包含以下标准流程：\r\n\r\n**1. 签到与欢迎（约15-30分钟）**\r\n- 家长签到领取资料袋，学校播放宣传视频。\r\n- 由学生志愿者引导进入会场。\r\n\r\n**2. 校长/领导宣讲（约45-60分钟）**\r\n- 介绍学校办学理念、教育特色、管理团队。\r\n- 说明招生政策和入学要求。\r\n- 展示学校升学成果和学生成就。\r\n\r\n**3. 校园参观（约30-45分钟）**\r\n- 由老师或学生志愿者带领家长参观校园。\r\n- 参观教室、图书馆、实验室、体育场馆、餐厅等设施。\r\n- 观察学生的上课状态和校园氛围。\r\n\r\n**4. 体验课（部分学校）**\r\n- 家长可旁听真实课堂或学校安排的体验课。\r\n- 感受课堂教学方式和师生互动氛围。\r\n\r\n**5. 现场咨询与答疑**\r\n- 与招生官、老师或在校家长进行深入交流。\r\n- 解答个性化问题。\r\n', NULL, NULL, 2, '2026-07-21 10:44:31');
INSERT INTO `guide_article` VALUES (33, '择校探校', '学校开放日', '国际学校开放日的开放时间', '\r\n国际学校开放日的时间安排通常分为两类：\r\n\r\n**1. 工作日开放日**：\r\n- 时间：通常安排在周二至周四的上午。\r\n- 优势：可以看到学校的真实教学状态，课堂和活动都在正常进行。\r\n- 适合人群：时间灵活的家长。\r\n\r\n**2. 周末开放日**：\r\n- 时间：通常安排在周六上午或下午。\r\n- 优势：方便双职工家长参加。\r\n- 注意事项：部分学校会安排学生展示或文艺表演。\r\n\r\n**3. 开放日主要集中在以下时间段**：\r\n- 春季招生季：3月-5月\r\n- 秋季招生季：10月-12月\r\n- 具体时间以各校官网发布的招生简章为准。\r\n\r\n**4. 预约注意事项**：\r\n- 绝大多数学校要求提前预约，不接受空降。\r\n- 部分热门学校名额有限，建议尽早预约。\r\n- 关注学校官网或微信公众号获取最新开放日信息。\r\n', NULL, NULL, 3, '2026-07-21 10:44:31');
INSERT INTO `guide_article` VALUES (34, '择校探校', '学校开放日', '公立学校国际部开放日流程', '\r\n公立学校国际部的开放日与传统国际学校略有不同，流程一般如下：\r\n\r\n**1. 学校整体介绍**：\r\n- 由校领导介绍学校的办学历史、办学特色和整体情况。\r\n- 重点介绍国际部的定位、发展历程和办学成果。\r\n\r\n**2. 国际部课程与教学宣讲**：\r\n- 详细说明国际部的课程体系、师资配备和教学特色。\r\n- 介绍升学指导服务和毕业生去向。\r\n\r\n**3. 招生政策说明**：\r\n- 重点说明招生对象（通常限本地户籍）、招生名额、录取方式。\r\n- 解释中考成绩要求、加试安排及录取流程。\r\n\r\n**4. 校园参观**：\r\n- 参观国际部的专用教学区域和设施。\r\n- 了解国际部与学校其他部门的资源共享情况。\r\n\r\n**5. 现场答疑**：\r\n- 招生办老师解答家长关于入学流程、课程选择等具体问题。\r\n- 部分学校会安排在读学生或家长分享就读体验。\r\n\r\n**注意**：公立学校国际部的开放日通常与学校整体开放日同步或单独安排。\r\n', NULL, NULL, 4, '2026-07-21 10:44:31');
INSERT INTO `guide_article` VALUES (35, '择校探校', '学校开放日', '参加国际学校的开放日有什么用？', '\r\n参加国际学校开放日对家长和学生有重要价值：\r\n\r\n**1. 建立真实认知**：\r\n- 官网和宣传册之外的\"实际体验\"，感受真实的校园氛围。\r\n- 亲眼观察课堂状态、学生面貌、师生互动。\r\n\r\n**2. 评估学校与孩子的匹配度**：\r\n- 学校的教育理念是否与家庭教育观念一致？\r\n- 学校的培养模式是否适合孩子的性格特点？\r\n\r\n**3. 与关键人物直接交流**：\r\n- 与校长、老师、招生官面对面沟通。\r\n- 了解学校的真实情况，提问个性化问题。\r\n\r\n**4. 获取升学规划信息**：\r\n- 了解申请流程、时间节点和入学要求。\r\n- 获取当年招生名额和考试安排。\r\n\r\n**5. 帮助孩子做选择**：\r\n- 带孩子一起探校，让孩子感受学校氛围。\r\n- 孩子的直观感受是择校的重要参考。\r\n\r\n**建议**：参加开放日不是去\"盖章打卡\"，而是带着明确问题去深入考察。\r\n', NULL, NULL, 5, '2026-07-21 10:44:31');
INSERT INTO `guide_article` VALUES (36, '择校探校', '学校开放日', '学校开放日宣讲，家长需要重点了解以下方面！', '\r\n参加学校开放日宣讲会时，建议家长重点关注以下方面：\r\n\r\n**1. 办学理念与特色**：\r\n- 学校的核心价值观是什么？如何落实到日常教学中？\r\n\r\n**2. 课程体系**：\r\n- 学校提供哪些课程？（IB/AP/A-Level/国家课程）\r\n- 课程如何实施？是否有分层教学？\r\n\r\n**3. 师资力量**：\r\n- 中外教比例是多少？外教来自哪些国家？\r\n- 教师稳定性如何？教师培训体系如何？\r\n\r\n**4. 升学成果**：\r\n- 近三年毕业生主要去向（国家、大学排名、专业分布）。\r\n- 学校对学生的升学指导支持如何？\r\n\r\n**5. 招生政策**：\r\n- 招生对象、名额、学费、奖学金政策。\r\n- 入学考试形式（笔试科目、面试形式）。\r\n\r\n**6. 学生管理**：\r\n- 学生管理制度（手机管理、考勤等）。\r\n- 心理健康支持和辅导体系。\r\n\r\n**7. 家校沟通**：\r\n- 家长与学校的沟通机制和频率。\r\n- 家长是否参与学校事务的决策？\r\n', NULL, NULL, 6, '2026-07-21 10:44:31');
INSERT INTO `guide_article` VALUES (37, '择校探校', '学校开放日', '参观学校开放日要带什么？', '\r\n参加学校开放日建议提前准备以下物品和材料：\r\n\r\n**1. 必备物品**：\r\n- 身份证或其他有效证件（用于签到）。\r\n- 笔和笔记本（记录关键信息）。\r\n- 手机（拍照、录音、查看学校地图）。\r\n\r\n**2. 孩子相关材料**：\r\n- 孩子的简历或成长档案（如有）。\r\n- 孩子近期成绩单或证书（如有）。\r\n- 孩子的护照照片（部分学校现场报名需要）。\r\n\r\n**3. 准备问题清单**：\r\n提前写好想提问的问题，避免现场遗漏。\r\n\r\n**4. 着装建议**：\r\n- 家长着装得体即可。\r\n- 如带孩子参加，建议穿着整洁大方。\r\n\r\n**5. 陪同意愿**：\r\n- 确认学校是否欢迎学生参加开放日。\r\n- 部分学校要求带孩子参加体验课或面试。\r\n\r\n**6. 检查清单**：\r\n- 是否已提前预约？\r\n- 是否已确认时间和地点？\r\n- 是否有停车位或其他交通安排？\r\n', NULL, NULL, 7, '2026-07-21 10:44:31');
INSERT INTO `guide_article` VALUES (38, '择校探校', '报考要求', '国际学校入学要求', '\r\n国际学校的入学要求因学校类型和学段而异，一般包括以下方面：\r\n\r\n**1. 年龄要求**：\r\n- 按学校规定的入学年龄标准，一般按9月1日出生划分年级。\r\n\r\n**2. 身份要求**：\r\n- 民办国际学校：不限户籍，全国招生。\r\n- 外籍人员子女学校：要求学生持有外国护照或港澳台身份。\r\n- 公立学校国际部：通常限本地户籍。\r\n\r\n**3. 学术要求**：\r\n- 需提供过往成绩单，部分学校有GPA门槛。\r\n- 需参加学校自主命题的入学考试（笔试+面试）。\r\n\r\n**4. 语言要求**：\r\n- 英语能力是重要考核指标，部分学校要求提供标化成绩（TOEFL Junior/IELTS/TOEFL）。\r\n- 国际学校英语面试考察口语表达能力。\r\n\r\n**5. 入学考试内容**：\r\n- 笔试：英语、数学（部分学校增加科学、语文）。\r\n- 面试：学生面试（中英双语）+家长面试。\r\n\r\n**6. 其他材料**：\r\n- 推荐信（由当前学校老师提供）。\r\n- 获奖证书、课外活动证明（如有）。\r\n', NULL, NULL, 1, '2026-07-21 10:44:31');
INSERT INTO `guide_article` VALUES (39, '择校探校', '报考要求', '上海公立国际部报考要求', '\r\n上海公立学校国际部的报考要求具有以下特点：\r\n\r\n**1. 招生对象**：\r\n- 通常仅招收上海本地户籍学生。\r\n- 部分学校接受符合上海市中考报名条件的非本地户籍学生。\r\n\r\n**2. 中考成绩要求**：\r\n- 需参加上海市中考，成绩达到学校规定的录取分数线。\r\n- 部分学校自主划定录取分数线，高于普通班录取线。\r\n\r\n**3. 加试环节**：\r\n- 中考后参加学校组织的英语加试和面试。\r\n- 加试内容：英语笔试（阅读、写作）+英语口语面试。\r\n\r\n**4. 综合素质评价**：\r\n- 参考学生初中阶段的综合素质评价报告。\r\n- 重视学生的特长、获奖情况和社会实践经历。\r\n\r\n**5. 招生流程**：\r\n- 中考前：参加学校开放日，了解招生政策。\r\n- 中考后：提交申请材料，参加加试和面试。\r\n- 录取：根据中考成绩+加试成绩综合择优录取。\r\n\r\n**6. 部分学校**：上海中学国际部、华师大二附中国际部、复旦附中国际部等。\r\n', NULL, NULL, 2, '2026-07-21 10:44:31');
INSERT INTO `guide_article` VALUES (40, '递交申请', '如何申请', '一文搞懂国际学校申请流程', '\r\n国际学校申请一般包含以下流程：\r\n\r\n**1. 信息收集与择校（前1-2年）**：\r\n- 了解不同国际学校的课程体系、办学特色和升学成果。\r\n- 结合孩子情况和家庭需求确定目标学校。\r\n\r\n**2. 参加开放日（前1年）**：\r\n- 预约并参加目标学校的开放日或探校活动。\r\n- 与招生官、老师、在校家长深入交流。\r\n\r\n**3. 提交申请（前1年秋季至当年春季）**：\r\n- 在线填写申请表格，提交以下材料：\r\n  - 学生身份证明（户口本/护照等）\r\n  - 过往成绩单（最近2-3年）\r\n  - 推荐信（由当前学校老师提供）\r\n  - 获奖证书和课外活动证明\r\n\r\n**4. 参加入学考试（当年春季）**：\r\n- 笔试：英语、数学（部分学校增加科学）\r\n- 面试：学生面试+家长面试\r\n\r\n**5. 录取与确认（当年3-6月）**：\r\n- 学校发放录取通知书。\r\n- 在规定时间内确认学位并缴纳留位费。\r\n\r\n**6. 入学准备（暑假）**：\r\n- 语言提升、课程预习、做好心理准备。\r\n', NULL, NULL, 1, '2026-07-21 10:44:31');
INSERT INTO `guide_article` VALUES (41, '递交申请', '申请时间', '国际学校申请时间线', '\r\n国际学校申请全年时间线梳理：\r\n\r\n**秋季学期申请（主要招生季）**：\r\n- 前一年9-10月：学校发布招生简章，开放申请通道。\r\n- 前一年11-12月：参加开放日，提交申请材料。\r\n- 当年1-2月：参加入学考试（笔试+面试）。\r\n- 当年3-4月：收到录取结果，确认学位。\r\n\r\n**春季学期申请（插班/补录）**：\r\n- 前一年10-12月：了解插班名额和补录政策。\r\n- 当年1月：提交插班申请材料。\r\n- 当年1-2月：参加插班入学考试。\r\n- 当年2-3月：收到录取结果，准备春季入学。\r\n\r\n**滚动招生**：\r\n- 部分学校全年接受申请，有名额即可安排考试。\r\n- 建议至少提前3-6个月提交申请。\r\n\r\n**关键提醒**：\r\n- 热门学校名额有限，建议提前1-2年开始规划。\r\n- 各校具体时间以官网发布为准。\r\n- 幼升小、小升初节点需特别关注教委入学政策。\r\n', NULL, NULL, 1, '2026-07-21 10:44:31');
INSERT INTO `guide_article` VALUES (42, '递交申请', '申请时间', '国际学校申请时间线规划', '\r\n国际学校申请建议至少提前1-2年开始规划：\r\n\r\n**提前18-24个月：择校信息收集**\r\n- 了解不同课程体系（IB/AP/A-Level）特点及升学方向。\r\n- 收集目标学校的师资、升学成果、学费等信息。\r\n- 初步确定3-5所目标学校。\r\n\r\n**提前12-18个月：深度了解与准备**\r\n- 参加学校开放日，实地探校。\r\n- 与在读家长交流，获取真实就读体验。\r\n- 开始语言提升计划（英语听说读写能力）。\r\n\r\n**提前9-12个月：申请材料准备**\r\n- 准备成绩单、推荐信、获奖证书等申请材料。\r\n- 根据目标学校要求准备个人陈述或学生文书。\r\n\r\n**提前6-9个月：参加入学考试**\r\n- 针对目标学校的考试形式进行备考。\r\n- 参加笔试（英语+数学）和面试（学生+家长）。\r\n\r\n**提前3-6个月：录取与确认**\r\n- 收到录取通知后确认学位。\r\n- 缴纳留位费，完成注册手续。\r\n\r\n**入学前暑假：入学准备**\r\n- 语言强化学习，适应全英文环境。\r\n- 预习国际课程内容，做好衔接准备。\r\n', NULL, NULL, 2, '2026-07-21 10:44:31');
INSERT INTO `guide_article` VALUES (43, '递交申请', '申请材料', '国际学校申请材料包括哪些？', '\r\n申请国际学校通常需要准备以下材料：\r\n\r\n**1. 身份证明文件**：\r\n- 学生身份证/户口本或护照复印件。\r\n- 父母身份证或护照复印件。\r\n\r\n**2. 过往成绩单**：\r\n- 最近2-3年的学校成绩单（需学校盖章）。\r\n- 部分学校要求提供成绩单的中英文翻译件。\r\n\r\n**3. 推荐信**：\r\n- 通常由当前学校班主任或学科老师撰写。\r\n- 推荐信应重点评价学生的学术能力、性格特点和发展潜力。\r\n\r\n**4. 学生个人陈述（部分学校）**：\r\n- 介绍自己的兴趣爱好、学术目标和个人成长经历。\r\n- 说明为什么选择这所学校。\r\n\r\n**5. 获奖证书和课外活动证明**：\r\n- 提供学生在艺术、体育、竞赛等方面的获奖证书。\r\n- 记录学生参加的课外活动和社会实践经历。\r\n\r\n**6. 入学申请表**：\r\n- 填写学校官方提供的入学申请表。\r\n\r\n**7. 其他材料**：\r\n- 体检报告（部分学校要求）。\r\n- 英语标化成绩（TOEFL Junior/IELTS/TOEFL）。\r\n- 学校要求的其他补充材料。\r\n', NULL, NULL, 1, '2026-07-21 10:44:31');
INSERT INTO `guide_article` VALUES (44, '递交申请', '申请材料', '公立学校国际部申请材料需要哪些？', '\r\n申请公立学校国际部通常需要准备以下材料：\r\n\r\n**1. 身份及户籍材料**：\r\n- 学生户口本原件及复印件。\r\n- 父母身份证复印件。\r\n- 符合上海市中考报名条件的证明。\r\n\r\n**2. 中考成绩**：\r\n- 上海市中考成绩单。\r\n- 达到学校规定的录取分数线。\r\n\r\n**3. 初中阶段成绩单**：\r\n- 初中三年的完整成绩单（学校盖章）。\r\n- 部分学校要求提供年级排名证明。\r\n\r\n**4. 国际部加试相关材料**：\r\n- 国际部自主招生报名表。\r\n- 英语能力证明（TOEFL Junior/IELTS/TOEFL成绩）。\r\n- 获奖证书（校级以上奖励优先）。\r\n\r\n**5. 综合素质评价材料**：\r\n- 初中综合素质评价报告。\r\n- 推荐信（由初中学校出具）。\r\n- 个人陈述或申请文书（部分学校要求）。\r\n\r\n**6. 学生证件照**：\r\n- 近期一寸免冠照片数张。\r\n\r\n**注意**：各校具体要求以学校招生简章为准。\r\n', NULL, NULL, 2, '2026-07-21 10:44:31');
INSERT INTO `guide_article` VALUES (45, '递交申请', '申请材料', '外籍人员子女学校申请材料需要哪些？', '\r\n申请外籍人员子女学校（国际学校）需要准备以下材料：\r\n\r\n**1. 身份证明材料**：\r\n- 学生外国护照及有效签证复印件。\r\n- 学生出生证明（须经公证或认证）。\r\n- 父母外国护照及有效签证复印件。\r\n- 学生及父母的在华居留许可。\r\n\r\n**2. 过往成绩单**：\r\n- 最近2-3年的学校成绩单（中英文或全英文）。\r\n- 成绩单需由当前学校盖章。\r\n\r\n**3. 推荐信**：\r\n- 通常由当前学校老师或校长撰写。\r\n- 需为英文推荐信。\r\n\r\n**4. 学生评估/个人介绍**：\r\n- 学生个人介绍或学习经历陈述。\r\n- 部分学校要求提供学生的学习评估报告。\r\n\r\n**5. 英语能力证明**：\r\n- 非英语母语学生可能需要提供英语标化成绩（TOEFL Junior、IELTS等）。\r\n- 部分学校提供ESL/EAL支持。\r\n\r\n**6. 其他材料**：\r\n- 学生近期照片。\r\n- 疫苗接种记录。\r\n- 学校要求的其他补充材料（如儿童保护声明等）。\r\n\r\n**注意**：外籍人员子女学校的申请要求各校差异较大，建议提前联系招生办确认。\r\n', NULL, NULL, 3, '2026-07-21 10:44:31');
INSERT INTO `guide_article` VALUES (46, '递交申请', '入学测试', '国际学校入学笔面试分别是什么？', '\r\n国际学校入学考试通常包含笔试和面试两个环节：\r\n\r\n**笔试部分**：\r\n- **英语**：考察阅读、写作、语法等综合语言能力。\r\n- **数学**：考察逻辑思维和数学基础能力（通常为英文出题）。\r\n- **科学/语文**：部分学校增加科学（物理、化学、生物）或语文考试。\r\n- 考试难度因学校和学生年级而异，低年级以基础考察为主，高年级难度递升。\r\n\r\n**面试部分**：\r\n- **学生面试**：\r\n  - 考察英语口语表达能力和沟通能力。\r\n  - 评估学生的性格特点、兴趣爱好和学习动机。\r\n  - 问题示例：\"你喜欢阅读什么书？\"\"为什么想来我们学校？\"\r\n- **家长面试**（部分学校）：\r\n  - 了解家庭的教育理念和价值观。\r\n  - 考察家长对学校的了解程度和配合意愿。\r\n  - 问题示例：\"您对孩子的未来有什么期望？\"\"您如何评价目前的教育体系？\"\r\n\r\n**面试形式**：一对一、小组面试或情景互动，部分学校为全英文面试。\r\n', NULL, NULL, 1, '2026-07-21 10:44:31');
INSERT INTO `guide_article` VALUES (47, '递交申请', '入学测试', '上海国际学校常见的4种标准化入学考试类型', '\r\n上海国际学校常见的标准化入学考试包括以下四种：\r\n\r\n**1. MAP（学业进度评估）**：\r\n- 美式学校常用（如上海美国学校）。\r\n- 自适应机考，考察阅读、数学、语言运用等科目。\r\n- 考试时长：约1-2小时。\r\n\r\n**2. CAT4（认知能力测试）**：\r\n- 英式学校常用（如德威、惠灵顿）。\r\n- 考察语言推理、非语言推理、数量推理和空间能力。\r\n- 考试时长：约2小时。\r\n\r\n**3. WIDA（语言评估）**：\r\n- 测试英语学习者的听说读写能力。\r\n- 用于评估非英语母语学生的语言水平。\r\n- 考试时长：约1-2小时。\r\n\r\n**4. 学校自命题考试**：\r\n- 多数民办双语学校采用自己命题的入学测试。\r\n- 通常考察：英语笔试+数学笔试+英文面试。\r\n- 题型灵活，因校而异。\r\n\r\n**选择建议**：根据目标学校的考试类型针对性备考。\r\n', NULL, NULL, 2, '2026-07-21 10:44:31');
INSERT INTO `guide_article` VALUES (48, '递交申请', '入学测试', '入学考试 | 国际学校入学考试类型', '\r\n国际学校入学考试类型多样，主要分为以下几类：\r\n\r\n**1. 学校自主命题考试**：\r\n- 适用范围：大多数民办双语学校。\r\n- 考察内容：英语（阅读/写作/语法）、数学（英文出题）、英语面试。\r\n- 特点：各校题型和难度差异较大，需针对性备考。\r\n\r\n**2. 标准化考试**：\r\n- MAP：美式学校常用的自适应机考。\r\n- CAT4：英式学校常用的认知能力测试。\r\n- WIDA：评估英语学习者的语言水平。\r\n- 特点：有统一的评分标准，适合跨校申请。\r\n\r\n**3. 中考成绩+加试**：\r\n- 适用范围：公立学校国际部。\r\n- 要求：中考成绩达到学校分数线，再加试英语和面试。\r\n- 特点：需同时兼顾中考和国际部加试备考。\r\n\r\n**4. UKiset/ISEE等**：\r\n- 部分学校还接受UKiset（英国私立学校入学考试）或ISEE成绩。\r\n- 适用于申请海外学校的国际学生。\r\n\r\n**备考建议**：提前了解目标学校的考试形式，制定针对性备考计划。\r\n', NULL, NULL, 3, '2026-07-21 10:44:31');
INSERT INTO `guide_article` VALUES (49, '递交申请', '入学测试', 'UKiset | 国际学校入学考试介绍', '\r\n**UKiset（英国独立学校入学考试）简介**：\r\n\r\n**考试目的**：\r\n- 用于评估非英国籍学生申请英国私立学校的学术潜力和英语能力。\r\n- 也被部分中国国际学校采纳为入学评估标准。\r\n\r\n**考试内容**：\r\n1. **语言推理**：考察词汇、语法和逻辑能力。\r\n2. **非语言推理**：考察图形识别和逻辑推理能力。\r\n3. **数学推理**：考察数学逻辑和应用能力。\r\n4. **英语能力**：阅读、写作、听力、口语。\r\n\r\n**考试形式**：\r\n- 在线机考，自适应难度。\r\n- 考试时长：约2小时。\r\n\r\n**适用范围**：\r\n- 9-18岁申请英国私立学校的学生。\r\n- 部分中国国际学校将UKiset作为入学参考。\r\n\r\n**成绩报告**：\r\n- 提供详细的成绩报告，展示各科得分和百分位排名。\r\n\r\n**备考建议**：\r\n- 重点加强英语词汇和阅读理解能力。\r\n- 熟悉题型和考试流程，进行模拟练习。\r\n', NULL, NULL, 4, '2026-07-21 10:44:31');
INSERT INTO `guide_article` VALUES (50, '递交申请', '入学测试', 'MAP | 国际学校入学考试介绍', '\r\n**MAP（学业进度评估）考试简介**：\r\n\r\n**考试目的**：\r\n- 美国西北测评协会（NWEA）开发的标准化考试。\r\n- 用于评估学生的学业进度和能力水平，在国际学校中广泛应用。\r\n\r\n**考试科目**：\r\n1. **阅读**：词汇理解、文学作品分析、信息文本分析。\r\n2. **语言运用**：语法、写作技巧和语言规范。\r\n3. **数学**：数感、运算、代数、几何、数据统计。\r\n4. **科学**（部分学校）：生命科学、物理科学、地球科学。\r\n\r\n**考试形式**：\r\n- 计算机自适应机考。\r\n- 题量约40-53题，总时长约1-2小时。\r\n- 题目难度随考生答题情况动态调整。\r\n\r\n**适用范围**：\r\n- K-12学生，考试内容根据年级水平调整。\r\n- 美式国际学校广泛使用。\r\n\r\n**成绩报告**：\r\n- 提供RIT分数（衡量学生当前水平的分数体系）。\r\n- 展示学生在全国常模中的百分位排名。\r\n\r\n**备考建议**：\r\n- 熟悉题型和考试界面。\r\n- 积累学科词汇和阅读能力。\r\n', NULL, NULL, 5, '2026-07-21 10:44:31');
INSERT INTO `guide_article` VALUES (51, '递交申请', '入学测试', 'ISEE | 国际学校入学考试介绍', '\r\n**ISEE（独立学校入学考试）简介**：\r\n\r\n**考试目的**：\r\n- 由美国教育记录局（ERB）开发，用于申请美国私立学校。\r\n- 被全球超过1200所独立学校认可，包括美国、加拿大等国的顶尖私校。\r\n\r\n**考试级别**：\r\n- **初级（Primary）**：申请2-4年级（分2、3、4三个独立级别）。\r\n- **低级别（Lower）**：申请5-6年级。\r\n- **中级别（Middle）**：申请7-8年级。\r\n- **高级别（Upper）**：申请9-12年级。\r\n\r\n**考试科目**：\r\n1. **语言推理**：词汇、句子填空、逻辑。\r\n2. **数量推理**：数学思维和逻辑能力。\r\n3. **阅读理解**：多篇文章阅读理解。\r\n4. **数学**：数学知识和应用能力。\r\n5. **写作**：命题作文（不计分但提交给学校）。\r\n\r\n**考试形式**：\r\n- 纸笔考试或机考。\r\n- 写作部分不计分但需提交给申请学校。\r\n\r\n**备考建议**：\r\n- 根据申请年级选择对应级别。\r\n- 重点加强词汇量、逻辑思维和写作能力。\r\n', NULL, NULL, 6, '2026-07-21 10:44:31');
INSERT INTO `guide_article` VALUES (52, '递交申请', '入学测试', 'CEPT | 国际学校入学考试介绍', '\r\n**CEPT（剑桥英语分级测试）简介**：\r\n\r\n**考试目的**：\r\n- 由剑桥大学英语考评部开发。\r\n- 用于快速评估学生的英语听力和阅读能力。\r\n\r\n**考试内容**：\r\n1. **听力部分**：\r\n   - 考察日常对话、学术场景等不同语境下的听力理解能力。\r\n   - 题型：选择题、填空题、配对题。\r\n2. **阅读部分**：\r\n   - 考察词汇、语法和阅读理解能力。\r\n   - 题型：完形填空、阅读理解选择题。\r\n\r\n**考试形式**：\r\n- 计算机自适应机考。\r\n- 考试时长：约30分钟。\r\n- 题目难度根据考生答题情况动态调整。\r\n\r\n**分数报告**：\r\n- 提供CEFR级别（A1-C2）评估。\r\n- 展示听力和阅读两个维度得分。\r\n\r\n**适用范围**：\r\n- 部分国际学校将其作为英语能力测试工具。\r\n- 用于评估学生是否适合入读相应年级。\r\n\r\n**备考建议**：\r\n- 重点是提升综合英语能力。\r\n- 练习剑桥英语相关题型。\r\n', NULL, NULL, 7, '2026-07-21 10:44:31');
INSERT INTO `guide_article` VALUES (53, '递交申请', '入学测试', 'CEM | 国际学校入学考试介绍', '\r\n**CEM（剑桥评估中心考试）简介**：\r\n\r\n**考试目的**：\r\n- 由剑桥大学下属机构CEM开发。\r\n- 用于评估学生的学术潜力和认知能力。\r\n\r\n**考试内容**：\r\nCEM考试一般包含以下模块：\r\n1. **语言推理**：\r\n   - 文字逻辑、词汇理解和推理能力。\r\n   - 题型：文字类比、句子填空等。\r\n2. **非语言推理**：\r\n   - 图形推理、空间能力和逻辑思维。\r\n   - 题型：图形分类、序列推理等。\r\n3. **数学推理**：\r\n   - 数学逻辑和应用能力。\r\n   - 题型：应用题、数据分析等。\r\n\r\n**考试形式**：\r\n- 纸笔或机考。\r\n- 考试时长因级别和模块而异。\r\n\r\n**适用范围**：\r\n- 部分英式国际学校用于入学评估。\r\n- 也用于学校内部阶段性评估。\r\n\r\n**分数报告**：\r\n- 提供各模块得分和整体评估结果。\r\n- 展示学生在同龄人中的相对位置。\r\n\r\n**备考建议**：\r\n- 重点训练逻辑推理和批判性思维能力。\r\n- 通过模拟练习熟悉题型和考试节奏。\r\n', NULL, NULL, 8, '2026-07-21 10:44:31');
INSERT INTO `guide_article` VALUES (54, '递交申请', '入学测试', 'CAT4 | 国际学校入学考试介绍', '\r\n**CAT4（认知能力测试）考试简介**：\r\n\r\n**考试目的**：\r\n- 由英国GL Assessment开发。\r\n- 用于评估学生的认知能力和学术潜力，而非学科知识。\r\n\r\n**考试内容**（四个维度）：\r\n1. **语言推理**：\r\n   - 考察文字逻辑和词汇理解能力。\r\n   - 题型：文字分类、文字类比等。\r\n2. **非语言推理**：\r\n   - 考察图形识别和逻辑推理能力。\r\n   - 题型：图形矩阵、图形分类等。\r\n3. **数量推理**：\r\n   - 考察数字逻辑和数学推理能力。\r\n   - 题型：数字类比、数列推理等。\r\n4. **空间能力**：\r\n   - 考察三维空间想象和思维能力。\r\n   - 题型：折纸、三维旋转等。\r\n\r\n**考试形式**：\r\n- 机考或纸笔考试。\r\n- 考试时长：约2小时。\r\n\r\n**适用范围**：\r\n- 英式国际学校（如德威、惠灵顿）普遍采用。\r\n\r\n**成绩报告**：\r\n- 提供SAS（标准化年龄分数）、NPR（全国百分位排名）等数据。\r\n\r\n**备考建议**：\r\n- 重点训练逻辑推理和空间想象能力。\r\n- 通过模拟题库熟悉题型。\r\n', NULL, NULL, 9, '2026-07-21 10:44:31');
INSERT INTO `guide_article` VALUES (55, '递交申请', '入学测试', 'AEIS | 国际学校入学考试介绍', '\r\n**AEIS（新加坡国际学生入学考试）简介**：\r\n\r\n**考试目的**：\r\n- 新加坡教育部为国际学生设计的入学考试。\r\n- 用于评估国际学生是否有资格入读新加坡公立中小学。\r\n\r\n**考试级别**：\r\n- 小学组：2-5年级（申请P2-P5）。\r\n- 中学组：1-3年级（申请S1-S3）。\r\n\r\n**考试科目**：\r\n1. **英语**：\r\n   - 写作：低年级看图作文，高年级命题作文（100-300词不等）。\r\n   - 阅读和语言运用：词汇选择、语法填空、阅读理解。\r\n2. **数学**：\r\n   - 包括选择题和简答题。\r\n   - 考察逻辑思维和数学应用能力。\r\n\r\n**考试形式**：\r\n- 纸笔考试。\r\n- 每年2月和9月各一次。\r\n\r\n**成绩报告**：\r\n- 根据考试成绩和学校名额择优录取。\r\n\r\n**备考建议**：\r\n- 重点加强英语词汇积累和写作能力。\r\n- 熟悉新加坡数学大纲内容。\r\n- 因每年仅两次考试机会，建议提前半年开始规划。\r\n', NULL, NULL, 10, '2026-07-21 10:44:31');
INSERT INTO `guide_article` VALUES (56, '递交申请', '入学测试', 'AEAS | 国际学校入学考试介绍', '\r\n**AEAS（澳大利亚教育评估服务考试）简介**：\r\n\r\n**考试目的**：\r\n- 由澳大利亚教育评估服务机构开发。\r\n- 用于评估国际学生申请澳大利亚中小学的学术能力。\r\n\r\n**考试内容**：\r\n1. **英语能力**：\r\n   - 词汇、阅读理解、写作、听力和口语。\r\n   - 时长约2小时。\r\n2. **数学推理**：\r\n   - 数学逻辑和应用能力，全英文出题。\r\n   - 时长约45分钟。\r\n3. **非语言推理**：\r\n   - 图形推理和逻辑能力，不受语言影响。\r\n   - 时长约30分钟。\r\n\r\n**考试形式**：\r\n- 纸笔考试。\r\n- 在中国多个城市设有考点。\r\n\r\n**成绩报告**：\r\n- 提供详细的英语、数学和推理能力评估。\r\n- 推荐学生适合入读的年级。\r\n- 英语能力部分给出具体分数和等级（A-E）。\r\n\r\n**适用范围**：\r\n- 申请澳大利亚私立和公立中小学的国际学生。\r\n- 部分中国国际学校也采纳AEAS作为入学评估。\r\n\r\n**备考建议**：\r\n- 重点提升英语综合应用能力。\r\n- 熟悉各题型，并进行模拟练习。\r\n', NULL, NULL, 11, '2026-07-21 10:44:31');
INSERT INTO `guide_article` VALUES (57, '录取准备', '录取须知', '录取国际高中≠“躺平”，拿到国际学校offer后需要做哪些规划？', '\r\n拿到国际学校录取通知书只是一个起点，入学前需做好以下规划：\r\n\r\n**1. 语言能力的持续提升**：\r\n- 国际高中全英文授课，英语能力直接影响听课和理解效果。\r\n- 暑假是语言提升的黄金期，建议集中强化英语听说读写能力。\r\n\r\n**2. 提前预习国际课程内容**：\r\n- 了解学校开设的课程体系（IB/AP/A-Level等）。\r\n- 预习数学、科学等学科的专业词汇和基础知识。\r\n- 培养批判性思维和独立思考能力。\r\n\r\n**3. 做好入学准备**：\r\n- 参加学校新生说明会、了解校园环境和规章制度。\r\n- 准备入学所需的学习用品和电子设备。\r\n- 与同龄新生建立联系，提前融入社交圈。\r\n\r\n**4. 调整心理状态**：\r\n- 全英文授课的新环境可能带来压力，提前做好心理准备。\r\n- 保持开放心态，愿意接受新的教学方式和评价体系。\r\n\r\n**核心思路**：录取不是终点，而是新征程的起点。\r\n', NULL, NULL, 1, '2026-07-21 10:50:04');
INSERT INTO `guide_article` VALUES (58, '录取准备', '录取须知', '又是开学又是分层考，录取国际学校后要做的三件大事，都准备好了吗？', '\r\n录取国际学校后，开学前务必做好以下三件大事：\r\n\r\n**第一件大事：语言能力提升**\r\n- 全英文授课环境是最大的挑战，暑假必须集中提升英语能力。\r\n- 积累学科专业词汇（数学、科学、人文等学科）。\r\n- 多听英文原版材料（播客、新闻、TED演讲），提升听力理解能力。\r\n- 练习英文写作和口语表达，开学后能更快适应课堂讨论。\r\n\r\n**第二件大事：提前预习课程内容**\r\n- 了解学校开设的课程体系和第一学期的主要教学内容。\r\n- 预习数学、科学等双语科目的核心知识点。\r\n- 适应英文出题的数学和科学题目，提前练习。\r\n\r\n**第三件大事：做好分层考试准备**\r\n- 很多国际学校在开学前或开学初会进行分层考试（分班考试）。\r\n- 分层考试决定孩子进入普通班还是进阶班。\r\n- 提前复习和准备，争取进入更适合孩子的学习层次。\r\n\r\n**核心提醒**：暑假是\"黄金预热期\"，充分利用这三个月，顺利适应国际高中学习。\r\n', NULL, NULL, 2, '2026-07-21 10:50:04');
INSERT INTO `guide_article` VALUES (59, '录取准备', '录取须知', '国际学校录取后，需要准备哪些入学设备？', '\r\n国际学校录取后，建议为入学准备以下设备和用品：\r\n\r\n**1. 电子设备**：\r\n- **笔记本电脑或平板电脑**：多数国际学校要求学生自备笔记本电脑（如MacBook或Windows笔记本），用于课堂学习和完成作业。\r\n- **手机**：用于日常通讯和学校通知（注意学校对手机使用的管理规定）。\r\n\r\n**2. 学习用品**：\r\n- 书包、笔记本、文件夹等基础文具。\r\n- 科学计算器（如TI-84，AP/IB考试常用）。\r\n- 英语-双语词典（电子词典或纸质词典）。\r\n\r\n**3. 校服与体育用品**：\r\n- 根据学校要求购买校服（夏装、冬装、运动服）。\r\n- 体育课所需运动鞋和运动装备（各校要求不同）。\r\n\r\n**4. 住宿用品（如需寄宿）**：\r\n- 床上用品（被褥、床单、枕头等）。\r\n- 生活用品（洗漱用品、毛巾、拖鞋、衣架等）。\r\n- 宿舍储物用品（收纳盒、挂锁等）。\r\n\r\n**建议**：提前查看学校发送的\"新生入学指南\"，按学校具体要求准备。\r\n', NULL, NULL, 3, '2026-07-21 10:50:04');
INSERT INTO `guide_article` VALUES (60, '录取准备', '入学问题', '进入国际学校后会遇到哪些问题？', '\r\n进入国际学校后，学生和家长常遇到以下挑战：\r\n\r\n**学生常见的困难**：\r\n1. **语言适应困难**：\r\n   - 全英文授课环境，学科专业词汇听不懂。\r\n   - 课堂讨论和英文写作要求较高。\r\n   - 建议：提前预习学科词汇，多听英文材料。\r\n\r\n2. **教学模式不适应**：\r\n   - 国际学校强调自主探究和批判性思维。\r\n   - 学生需要从\"被动学习\"转向\"主动学习\"。\r\n   - 建议：培养独立思考和主动提问的习惯。\r\n\r\n3. **社交融入困难**：\r\n   - 来自不同背景的同学，可能存在文化差异。\r\n   - 建议：积极参加课外活动，拓展社交圈。\r\n\r\n**家长常见的误区**：\r\n1. 以为进了国际学校就可以\"躺平\"。\r\n2. 期待孩子短期内英语水平大幅提升。\r\n3. 以应试思维评价国际学校的教学质量。\r\n\r\n**解决思路**：保持开放心态，给孩子适应时间，家长也需同步学习国际教育理念。\r\n', NULL, NULL, 1, '2026-07-21 10:50:04');
INSERT INTO `guide_article` VALUES (61, '录取准备', '入学问题', '国际学校入学后，家长需要做哪些准备？', '\r\n孩子入读国际学校后，家长也需要同步做好以下准备：\r\n\r\n**1. 理解国际教育理念**：\r\n- 国际学校重视全人教育，不只看分数。\r\n- 鼓励孩子发展兴趣爱好和个性特长。\r\n- 用成长型思维看待孩子的进步，不以一时成绩定论。\r\n\r\n**2. 积极参与家校沟通**：\r\n- 关注学校邮件和通知，了解孩子在校表现。\r\n- 积极参加家长会、家长讲座和学校活动。\r\n- 与老师保持良好沟通，了解孩子学习和成长情况。\r\n\r\n**3. 支持孩子的语言适应**：\r\n- 在家营造英文学习环境（英文书籍、电影、播客）。\r\n- 鼓励孩子用英文表达想法和感受。\r\n- 不急于求成，给孩子适应语言环境的时间。\r\n\r\n**4. 关注孩子的心理健康**：\r\n- 新环境的适应压力可能影响孩子情绪。\r\n- 多与孩子沟通，了解在校情况。\r\n- 帮助孩子建立积极的心态和应对压力的能力。\r\n\r\n**5. 调整期望值**：\r\n- 国际学校不是\"轻松教育\"，同样需要努力。\r\n- 但评价标准更多元化，不以一考定终身。\r\n', NULL, NULL, 2, '2026-07-21 10:50:04');
INSERT INTO `guide_article` VALUES (62, '录取准备', '开学时间', '国际学校开学时间临近，孩子怎么调整心态？', '\r\n国际学校开学临近，家长可帮助孩子从以下方面调整心态：\r\n\r\n**1. 提前熟悉新环境**：\r\n- 参加学校的新生说明会或新生营。\r\n- 实地参观校园，熟悉教室、餐厅、图书馆等位置。\r\n- 通过学校社交群与同届新生建立联系。\r\n\r\n**2. 建立合理的期望**：\r\n- 告诉孩子适应新环境需要时间，不必急于求成。\r\n- 英语水平提升是一个渐进过程，保持耐心。\r\n- 鼓励孩子对新学校持开放和好奇的态度。\r\n\r\n**3. 做好心理准备**：\r\n- 国际学校的教学方式与公办学校不同，需要适应。\r\n- 课堂讨论、小组合作、项目式学习是常见形式。\r\n- 鼓励孩子积极发言，不怕犯错。\r\n\r\n**4. 平衡焦虑与期待**：\r\n- 接受\"适应期\"的存在，给自己1-3个月的缓冲时间。\r\n- 保持与朋友的联络，缓解心理落差。\r\n\r\n**5. 家长的角色**：\r\n- 多倾听，少说教，理解孩子的焦虑和不安。\r\n- 与学校心理老师保持沟通，获取专业支持。\r\n', NULL, NULL, 1, '2026-07-21 10:50:04');
INSERT INTO `guide_article` VALUES (63, '录取准备', '开学时间', '转轨国际体系，开学前该如何准备学习？', '\r\n转轨国际体系后，开学前需从以下方面做好学习准备：\r\n\r\n**1. 语言准备（第一重点）**：\r\n- 强化英语听力：听英文播客、新闻、TED演讲，每天保持输入。\r\n- 积累学科词汇：数学、科学、人文等学科的专业词汇是理解课堂的基础。\r\n- 练习英文写作：熟悉学术写作的基本格式，练习英文段落写作和议论文写作。\r\n\r\n**2. 课程内容预习**：\r\n- 了解学校的课程设置和第一学期教学内容。\r\n- 选择自己擅长的科目进行预习，建立信心。\r\n- 预习数学、物理、化学等学科中的双语术语和基础概念。\r\n\r\n**3. 学习方法调整**：\r\n- 从\"刷题\"思维转向\"理解\"思维，注重知识的内在逻辑。\r\n- 培养批判性思维：学会提问、分析和评价。\r\n- 掌握时间管理技能：作业、项目、课外活动需合理分配时间。\r\n\r\n**4. 心理准备**：\r\n- 接受\"不适应\"是正常的，给自己适应时间。\r\n- 保持开放心态，愿意接受新事物和新挑战。\r\n\r\n**核心思路**：语言是基础，思维方法是关键，保持积极心态是保障。\r\n', NULL, NULL, 2, '2026-07-21 10:50:04');
INSERT INTO `guide_article` VALUES (64, '录取准备', '开学时间', '国际学校开学前，需要了解国际体系的考试？', '\r\n国际学校开学前，建议家长和学生了解国际课程体系的考试特点：\r\n\r\n**1. 国际课程考试的核心特点**：\r\n- **不是一考定终身**：多数国际课程采用\"平时成绩+大考成绩\"的综合评定方式。\r\n- **阶段性评估**：以IB为例，国际课程通常分散在2-3年内完成不同模块的考试，减轻最后阶段的集中压力。\r\n- **注重过程评价**：IA（内部评估）、论文、实验报告等计入最终成绩。\r\n\r\n**2. 不同课程体系的考试差异**：\r\n- **IB课程**：6大学科组+3大核心课程；每科1-7分，总分45分。\r\n- **A-Level**：分AS和A2两个阶段，可重考，选择3-4科。\r\n- **AP**：5分制，可自由选择科目数量，每年5月全球统考。\r\n- **OSSD**：过程性评价为主，70%平时成绩+30%期末成绩。\r\n\r\n**3. 学习规划建议**：\r\n- 深入了解所选课程体系的评估方式。\r\n- 平衡各科的学习和复习，合理分配时间。\r\n- 关注科目选择和背景提升的综合规划，提升竞争优势。\r\n', NULL, NULL, 3, '2026-07-21 10:50:04');
INSERT INTO `guide_article` VALUES (65, '录取准备', '提前学习', '国际学校开学前的假期学习要点', '\r\n国际学校开学前的假期是\"黄金预热期\"，以下学习要点供参考：\r\n\r\n**1. 英语是首要攻坚任务**：\r\n- 每天坚持英语听力训练（新闻、播客、TED演讲）。\r\n- 积累学科专业词汇，特别是数学、科学类术语。\r\n- 练习英语口语，模拟课堂发言场景，提升自信。\r\n\r\n**2. 了解所选课程体系**：\r\n- 了解IB/AP/A-Level等课程的基本框架和要求。\r\n- 明确目标留学方向（英/美/加/澳等），规划重点学习内容。\r\n- 了解高中三年各阶段的标化考试安排（托福、雅思、SAT等）。\r\n\r\n**3. 培养自主学习能力**：\r\n- 国际学校强调自主探究和独立思考。\r\n- 练习查找资料、写研究报告和项目展示等能力。\r\n- 培养时间管理和自我规划的习惯。\r\n\r\n**4. 明确三年规划路线**：\r\n- 根据目标大学和专业，合理规划科目选择和备考节奏。\r\n- 了解背景提升项目（竞赛、科研、社会实践）的重要性和时间安排。\r\n\r\n**核心目标**：开学后能尽快适应全英文授课和新的教学方式。\r\n', NULL, NULL, 1, '2026-07-21 10:50:04');
INSERT INTO `guide_article` VALUES (66, '录取准备', '提前学习', '进入国际学校不是万事大吉，高中三年如何规划学习？', '\r\n进入国际学校只是起点，高中三年需要系统规划：\r\n\r\n**高一：适应与奠基**\r\n- 英语能力持续提升，尽快适应全英文课堂环境。\r\n- 广泛探索学科兴趣，确定未来专业方向。\r\n- 确定目标留学国家和大学方向。\r\n- 开始语言成绩（雅思/托福）的准备。\r\n- 积极参加课外活动，拓展兴趣和视野。\r\n\r\n**高二：深化与冲刺**\r\n- 完成标化考试（雅思/托福/SAT等）首考。\r\n- 根据专业方向选择A-Level/AP/IB的具体科目。\r\n- 参加学术竞赛和科研项目，提升竞争力。\r\n- 准备暑期项目或夏校申请。\r\n\r\n**高三：冲刺与申请**\r\n- 完成标化考试的最后冲刺（如有需要）。\r\n- 准备大学申请材料（个人陈述、推荐信等）。\r\n- 提交大学申请（早申/常规申请）。\r\n- 准备面试和大学入学测试。\r\n\r\n**贯穿三年的核心**：保持GPA、积累学术活动、关注时间节点、合理规划每一步。\r\n', NULL, NULL, 2, '2026-07-21 10:50:04');
INSERT INTO `guide_article` VALUES (67, '录取准备', '提前学习', '公立国际部新高一，如何规划孩子的爬藤路？', '\r\n进入公立学校国际部后，目标是申请美国顶尖大学，建议做好以下规划：\r\n\r\n**1. 保持卓越的学术表现（GPA）**：\r\n- 美本申请中，GPA是核心指标之一。\r\n- 选择有挑战性的课程（荣誉课、AP课）。\r\n- 保持9-12年级持续优异的成绩。\r\n\r\n**2. 标准化考试规划**：\r\n- 高一：开始准备TOEFL/IELTS，争取首考达到100+。\r\n- 高二：准备SAT/ACT，争取达到1500+/34+。\r\n- 高二下学期：完成AP考试，展示学术竞争力。\r\n\r\n**3. 背景提升（全面发展）**：\r\n- 参加高质量的学术竞赛（如数学、物理、化学、生物奥赛）。\r\n- 参与科研项目或独立研究，展现学术热情。\r\n- 社团领导力、志愿服务、社会实践等积累深度而非广度。\r\n\r\n**4. 美本申请关键时间节点**：\r\n- 高一高二：持续积累学术和课外活动。\r\n- 高二暑假：参加夏校（美国大学学分项目）。\r\n- 高三上学期：完成申请材料撰写，提交ED/EA。\r\n\r\n**核心原则**：爬藤不是\"卷成绩\"，而是全面发展、持续卓越。\r\n', NULL, NULL, 3, '2026-07-21 10:50:04');
INSERT INTO `guide_article` VALUES (68, '录取准备', '提前学习', '国际生到底要不要做背景提升项目？', '\r\n背景提升（课外活动、竞赛、科研、社会实践等）对国际生升学的重要性：\r\n\r\n**1. 为什么要做背景提升？**\r\n- 顶尖大学招生不仅看成绩，更看重学生的综合素养。\r\n- 通过背景活动体现学术兴趣、领导力、社会责任感等品质。\r\n- 在学术成绩相近的情况下，优质背景活动是区分申请者的关键。\r\n\r\n**2. 哪些背景活动有含金量？**\r\n- **学术竞赛**：学科奥赛、数学建模、科学竞赛等。\r\n- **科研项目**：跟随教授或研究机构参与学术研究。\r\n- **领导力活动**：社团创始人、学生会干部、项目负责人等。\r\n- **社会服务**：有持续性和影响力的志愿服务。\r\n- **夏校**：顶尖大学举办的学分夏校或学术夏校。\r\n\r\n**3. 如何规划背景提升？**\r\n- **不是数量越多越好**：注重深度和持续度。\r\n- **与专业方向相关**：围绕目标专业打造\"学术故事线\"。\r\n- **高中三年渐进式规划**：高一探索、高二深耕、高三成果展示。\r\n\r\n**4. 哪些学生需要重点关注？**\r\n- 目标美国Top30/英国G5大学的学生。\r\n- 学术成绩优异但缺乏亮点的学生。\r\n', NULL, NULL, 4, '2026-07-21 10:50:04');
INSERT INTO `guide_article` VALUES (69, '录取准备', '提前学习', '背景提升是什么？如何规划有效的背景提升项目？', '\r\n**背景提升的定义**：\r\n- 指通过课外活动、竞赛、科研、社会实践等方式，提升学生的综合素质和学术竞争力。\r\n- 在留学申请中，背景活动是展示学生个性特质的重要途径。\r\n\r\n**如何规划有效的背景提升？**\r\n\r\n**第一步：明确目标**\r\n- 确定目标留学国家和大学层次。\r\n- 明确申请专业方向（STEM、人文社科、艺术等）。\r\n\r\n**第二步：时间规划**\r\n- 高一阶段：广泛尝试，探索兴趣方向。\r\n- 高二阶段：聚焦1-2个核心方向，深度参与。\r\n- 高三上学期：整理成果，完善申请材料。\r\n\r\n**第三步：项目选择原则**\r\n- **与专业相关**：围绕目标专业开展深度活动。\r\n- **持续投入**：长期坚持，展现热情和毅力。\r\n- **成果可见**：能体现产出（奖项、论文、作品、影响等）。\r\n- **差异化**：避免过于同质化的活动。\r\n\r\n**常见的背景提升项目类型**：\r\n1. 学术竞赛（数学/物理/化学/生物等学科奥赛）。\r\n2. 科研项目（跟随大学教授做研究、写论文）。\r\n3. 夏校项目（美国顶尖大学的学分项目）。\r\n4. 社会实践活动（支教、公益、社区服务等）。\r\n5. 领导力活动（创办社团、组织活动等）。\r\n\r\n**核心原则**：深度胜于广度，质量胜于数量。\r\n', NULL, NULL, 5, '2026-07-21 10:50:04');
